  // ParseJarvisDirectory recursively scans the 'Jarvis' directory for configuration files and extracts widget definitions.
  func ParseJarvisDirectory(dir string) ([]map[string]interface{}, error) {
      widgets := []map[string]interface{}{}
      err := filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
          if err != nil {
              return fmt.Errorf("error during file system traversal: %w", err)
          }
          if info.IsDir() {
              // Skip directories
              return nil
          }

          if !info.ModTime().IsZero() { // Ensure the last modified time is not zero (can be false positive for new files)
              configPath := path + ".jarvisConfig.json"
              if _, err = os.Stat(configPath); err == nil {
                  file, err := os.Open(path + ".jarvisConfig.json")
                  if err != nil {
                      return fmt.Errorf("error reading Jarvis Config: %w", err)
                  }
                  defer file.Close()

                  var jsonContent []byte
                  if jsonContent, err = io.ReadAll(file); err != nil {
                      return fmt.Errorf("error reading config JSON content: %w", err)
                  }

                  // Parse the JSON content to a map
                  widgetMap := make(map[string]interface{})
                  if err = json.Unmarshal(jsonContent, &widgetMap); err != nil {
                      return fmt.Errorf("failed to parse JSON in %s: %v", path, err)
                  }
                  widgets = append(widgets, widgetMap)
              } else {
                  // If the file doesn't exist for any reason
                  return nil
              }
          }

          return nil
      })

      if err != nil {
          return widgets, fmt.Errorf("error in ParseJarvisDirectory: %w", err)
      }

      return widgets, nil
  }
}

